class Solution {
  public int reversePairs(int[] nums) {
    return sortCount(nums, new int[nums.length], 0, nums.length);
  }

  private int sortCount(int[] a, int[] tmp, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) >>> 1;
    int count = sortCount(a, tmp, lo, mid) + sortCount(a, tmp, mid, hi);
    for (int i = lo, j = mid; i < mid; i++) {
      while (j < hi && a[i] > 2L * a[j]) j++;
      count += j - mid;
    }
    int i = lo, j = mid, k = lo;
    while (i < mid || j < hi) tmp[k++] = j == hi || (i < mid && a[i] <= a[j]) ? a[i++] : a[j++];
    System.arraycopy(tmp, lo, a, lo, hi - lo);
    return count;
  }
}
